import Image from 'next/image'
import Link from 'next/link'
import { ArrowRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type AboutGalleryImage = {
  src: string
  alt: string
}

export type AboutGalleryProps = {
  eyebrow?: string
  title: string
  description: string
  images: readonly AboutGalleryImage[]
  variant?: 'mosaic' | 'gallery' | 'editorial'
  stats?: readonly { value: string; label: string }[]
  action?: { label: string; href: string }
  mediaPosition?: 'left' | 'right'
  className?: string
}

export function AboutGallery({
  eyebrow,
  title,
  description,
  images,
  variant = 'mosaic',
  stats = [],
  action,
  mediaPosition = 'left',
  className,
}: AboutGalleryProps) {
  const visibleImages = images.slice(0, variant === 'gallery' ? 4 : 3)

  return (
    <section className={cn('overflow-hidden py-16 md:py-24', className)}>
      <div className="container grid items-center gap-10 lg:grid-cols-2 lg:gap-16">
        <div
          className={cn(
            'grid min-h-[460px] gap-3',
            variant === 'mosaic' && 'grid-cols-2 grid-rows-2',
            variant === 'gallery' && 'grid-cols-2 grid-rows-2',
            variant === 'editorial' && 'grid-cols-[1fr_.48fr] grid-rows-2',
            mediaPosition === 'right' && 'lg:order-2',
          )}
        >
          {visibleImages.map((image, index) => (
            <figure
              key={`${image.src}-${index}`}
              className={cn(
                'relative min-h-52 overflow-hidden rounded-3xl bg-muted',
                variant === 'mosaic' && index === 0 && 'row-span-2',
                variant === 'editorial' && index === 0 && 'row-span-2',
              )}
            >
              <Image
                src={image.src}
                alt={image.alt}
                fill
                className="object-cover transition-transform duration-700 hover:scale-105"
                sizes="(min-width: 1024px) 30vw, 50vw"
              />
            </figure>
          ))}
        </div>

        <div className={cn('max-w-xl', mediaPosition === 'right' && 'lg:order-1')}>
          {eyebrow ? (
            <p className="text-xs font-bold uppercase tracking-[0.2em] text-primary">{eyebrow}</p>
          ) : null}
          <h2 className="mt-4 text-3xl font-bold tracking-tight md:text-5xl">{title}</h2>
          <p className="mt-6 text-base leading-8 text-muted-foreground">{description}</p>

          {stats.length ? (
            <dl className="mt-8 grid grid-cols-2 gap-5 border-y py-6 sm:grid-cols-3">
              {stats.slice(0, 3).map((stat) => (
                <div key={`${stat.value}-${stat.label}`}>
                  <dt className="text-xs text-muted-foreground">{stat.label}</dt>
                  <dd className="mt-1 text-2xl font-bold">{stat.value}</dd>
                </div>
              ))}
            </dl>
          ) : null}

          {action ? (
            <Link
              href={action.href}
              className="mt-8 inline-flex items-center gap-2 rounded-sm font-semibold text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {action.label}
              <ArrowRight className="h-4 w-4" aria-hidden />
            </Link>
          ) : null}
        </div>
      </div>
    </section>
  )
}

import Image from 'next/image'
import type { HTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

export type GalleryGridItem = {
  src: string
  alt: string
  title?: string
  description?: string
  href?: string
  width?: number
  height?: number
}

export interface GalleryGridProps extends Omit<HTMLAttributes<HTMLElement>, 'children'> {
  items: readonly GalleryGridItem[]
  columns?: 2 | 3 | 4
  aspect?: 'square' | 'video' | 'portrait'
  variant?: 'grid' | 'masonry'
  emptyMessage?: string
}

export function GalleryGrid({
  items,
  columns = 3,
  aspect = 'square',
  variant = 'grid',
  emptyMessage = 'Nenhuma imagem disponível.',
  className,
  ...props
}: GalleryGridProps) {
  const columnsClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-2 lg:grid-cols-3',
    4: 'md:grid-cols-2 lg:grid-cols-4',
  }[columns]
  const aspectClass = { square: 'aspect-square', video: 'aspect-video', portrait: 'aspect-[3/4]' }[
    aspect
  ]

  if (!items.length) {
    return (
      <div
        className={cn(
          'rounded-2xl border border-dashed p-8 text-center text-muted-foreground',
          className,
        )}
      >
        {emptyMessage}
      </div>
    )
  }

  return (
    <section
      aria-label="Galeria de imagens"
      className={cn('grid grid-cols-1 gap-4', columnsClass, className)}
      {...props}
    >
      {items.map((item, index) => {
        const content = (
          <>
            <div
              className={cn(
                'relative overflow-hidden rounded-2xl bg-muted',
                variant === 'grid' && aspectClass,
              )}
            >
              <Image
                src={item.src}
                alt={item.alt}
                width={item.width ?? 900}
                height={item.height ?? 900}
                sizes={`(min-width: 1024px) ${Math.round(100 / columns)}vw, (min-width: 768px) 50vw, 100vw`}
                className={cn(
                  'h-full w-full object-cover transition duration-500 group-hover:scale-105',
                  variant === 'masonry' && 'h-auto',
                )}
              />
              {(item.title || item.description) && variant === 'grid' ? (
                <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 to-transparent p-5 pt-16 text-white">
                  {item.title ? <h3 className="font-semibold">{item.title}</h3> : null}
                  {item.description ? (
                    <p className="mt-1 text-sm text-white/80">{item.description}</p>
                  ) : null}
                </div>
              ) : null}
            </div>
            {(item.title || item.description) && variant === 'masonry' ? (
              <div className="px-1 pt-3">
                {item.title ? <h3 className="font-semibold">{item.title}</h3> : null}
                {item.description ? (
                  <p className="mt-1 text-sm text-muted-foreground">{item.description}</p>
                ) : null}
              </div>
            ) : null}
          </>
        )
        return item.href ? (
          <a
            key={`${item.src}-${index}`}
            href={item.href}
            className="group rounded-2xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          >
            {content}
          </a>
        ) : (
          <article key={`${item.src}-${index}`} className="group">
            {content}
          </article>
        )
      })}
    </section>
  )
}

import { Check } from 'lucide-react'
import { cn } from '@/lib/utils'

export type ProcessStepsProps = {
  title: string
  description?: string
  steps: Array<{ title: string; description: string }>
  className?: string
}

export function ProcessSteps({ title, description, steps, className }: ProcessStepsProps) {
  return (
    <section
      className={cn('bg-muted/30 py-16 md:py-24', className)}
      aria-labelledby="process-title"
    >
      <div className="container">
        <div className="max-w-2xl">
          <h2 id="process-title" className="text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
          {description ? <p className="mt-4 text-lg text-muted-foreground">{description}</p> : null}
        </div>
        <ol className="mt-10 grid gap-5 md:grid-cols-2 lg:grid-cols-4">
          {steps.map((step, index) => (
            <li
              key={step.title}
              className="relative rounded-2xl border bg-background p-6 shadow-sm"
            >
              <span className="flex h-10 w-10 items-center justify-center rounded-full bg-primary font-bold text-primary-foreground">
                {index + 1}
              </span>
              <h3 className="mt-5 text-lg font-semibold">{step.title}</h3>
              <p className="mt-2 text-sm leading-6 text-muted-foreground">{step.description}</p>
              {index === steps.length - 1 ? (
                <Check className="absolute right-5 top-5 h-5 w-5 text-primary" aria-hidden="true" />
              ) : null}
            </li>
          ))}
        </ol>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'
import { A11y, Autoplay, Keyboard, Navigation } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'

import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

import 'swiper/css'
import 'swiper/css/navigation'

export type ServiceCarouselItem = {
  id: string
  title: string
  description: string
  href: string
  image?: { src: string; alt: string }
  icon?: React.ReactNode
}

export type ServicesCarouselSectionProps = {
  eyebrow?: string
  title: string
  description?: string
  items: readonly ServiceCarouselItem[]
  action?: { label: string; href: string }
  autoplayDelay?: number | false
  className?: string
}

export function ServicesCarouselSection({
  eyebrow,
  title,
  description,
  items,
  action,
  autoplayDelay = false,
  className,
}: ServicesCarouselSectionProps) {
  const reducedMotion = useReducedMotion()

  return (
    <section className={cn('overflow-hidden bg-[#f4f0f6] py-20 md:py-28', className)}>
      <div className="container">
        <header className="flex flex-col gap-7 lg:flex-row lg:items-end lg:justify-between">
          <div className="max-w-3xl">
            {eyebrow ? (
              <p className="text-xs font-bold uppercase tracking-[0.24em] text-[#752871]">
                {eyebrow}
              </p>
            ) : null}
            <h2 className="mt-4 text-3xl font-bold tracking-tight text-[#10100e] md:text-5xl">
              {title}
            </h2>
            {description ? (
              <p className="mt-5 max-w-2xl leading-7 text-[#5a5560]">{description}</p>
            ) : null}
          </div>
          {action ? (
            <Link
              href={action.href}
              className="inline-flex w-fit items-center gap-2 rounded-full border border-[#752871]/20 bg-white px-5 py-3 text-sm font-semibold text-[#752871] transition hover:border-[#752871]/40 hover:shadow-md"
            >
              {action.label}
              <ArrowUpRight className="h-4 w-4" aria-hidden />
            </Link>
          ) : null}
        </header>

        <Swiper
          modules={[A11y, Autoplay, Keyboard, Navigation]}
          navigation
          keyboard={{ enabled: true }}
          autoplay={
            autoplayDelay && !reducedMotion
              ? { delay: autoplayDelay, pauseOnMouseEnter: true, disableOnInteraction: true }
              : false
          }
          spaceBetween={20}
          slidesPerView={1.08}
          breakpoints={{
            640: { slidesPerView: 2 },
            1024: { slidesPerView: 3 },
            1280: { slidesPerView: 3.4 },
          }}
          className="mt-12 !overflow-visible !pb-3"
        >
          {items.map((item, index) => (
            <SwiperSlide key={item.id} className="h-auto">
              <article className="group flex h-full min-h-[480px] flex-col overflow-hidden rounded-[2rem] border border-[#752871]/10 bg-white p-6 shadow-sm transition duration-300 hover:-translate-y-1 hover:shadow-xl">
                <div className="flex items-start justify-between gap-4">
                  <span className="text-xs font-bold tracking-[0.2em] text-[#752871]">
                    {String(index + 1).padStart(2, '0')}/{String(items.length).padStart(2, '0')}
                  </span>
                  {item.icon ? (
                    <span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#752871]/10 text-[#752871]">
                      {item.icon}
                    </span>
                  ) : null}
                </div>

                {item.image ? (
                  <div className="relative mt-7 aspect-[16/10] overflow-hidden rounded-2xl bg-[#ede8ef]">
                    <Image
                      src={item.image.src}
                      alt={item.image.alt}
                      fill
                      className="object-cover transition-transform duration-700 group-hover:scale-105"
                      sizes="(min-width: 1024px) 30vw, 80vw"
                    />
                  </div>
                ) : (
                  <div className="relative mt-7 aspect-[16/10] overflow-hidden rounded-2xl bg-[#3f2644]">
                    <span className="absolute -bottom-12 -right-8 h-44 w-44 rounded-full bg-[#752871]" />
                    <span className="absolute -left-8 top-8 h-32 w-32 rounded-[40%_60%] bg-[#9b4b96]" />
                  </div>
                )}

                <h3 className="mt-7 text-2xl font-semibold text-[#10100e]">{item.title}</h3>
                <p className="mt-3 line-clamp-3 text-sm leading-6 text-[#5a5560]">
                  {item.description}
                </p>
                <Link
                  href={item.href}
                  className="mt-auto inline-flex items-center gap-2 pt-6 text-sm font-semibold text-[#752871]"
                >
                  Leia mais
                  <ArrowUpRight
                    className="h-4 w-4 transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5"
                    aria-hidden
                  />
                </Link>
              </article>
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import { A11y, Keyboard, Navigation, Pagination } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'
import { Quote } from 'lucide-react'
import type { Testimonial } from './TestimonialsGrid'
import { cn } from '@/lib/utils'
import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'

export type TestimonialsCarouselProps = {
  title?: string
  testimonials: Testimonial[]
  className?: string
  label?: string
}

export function TestimonialsCarousel({
  title,
  testimonials,
  className,
  label = 'Depoimentos de clientes',
}: TestimonialsCarouselProps) {
  return (
    <section className={cn('py-16 md:py-24', className)} aria-label={label}>
      <div className="container">
        {title ? (
          <h2 className="mb-10 text-center text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        <Swiper
          modules={[A11y, Keyboard, Navigation, Pagination]}
          navigation
          pagination={{ clickable: true }}
          keyboard={{ enabled: true }}
          a11y={{ enabled: true }}
          spaceBetween={24}
          slidesPerView={1}
        >
          {testimonials.map((testimonial, index) => (
            <SwiperSlide key={`${testimonial.name}-${index}`}>
              <figure className="mx-auto max-w-3xl px-12 pb-12 text-center">
                <Quote className="mx-auto h-8 w-8 text-primary" aria-hidden="true" />
                <blockquote className="mt-5 text-xl leading-9 md:text-2xl">
                  &ldquo;{testimonial.quote}&rdquo;
                </blockquote>
                <figcaption className="mt-7 flex items-center justify-center gap-3">
                  {testimonial.avatar ? (
                    <Image
                      src={testimonial.avatar}
                      alt=""
                      width={48}
                      height={48}
                      className="h-12 w-12 rounded-full object-cover"
                    />
                  ) : null}
                  <span className="text-left">
                    <span className="block font-semibold">{testimonial.name}</span>
                    <span className="block text-sm text-muted-foreground">
                      {[testimonial.role, testimonial.company].filter(Boolean).join(' · ')}
                    </span>
                  </span>
                </figcaption>
              </figure>
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </section>
  )
}

import Image from 'next/image'
import { Quote } from 'lucide-react'
import { cn } from '@/lib/utils'

export type Testimonial = {
  quote: string
  name: string
  role?: string
  company?: string
  avatar?: string
}
export type TestimonialsGridProps = {
  title?: string
  testimonials: Testimonial[]
  className?: string
}

export function TestimonialsGrid({ title, testimonials, className }: TestimonialsGridProps) {
  return (
    <section
      className={cn('bg-muted/30 py-16 md:py-24', className)}
      aria-labelledby={title ? 'testimonials-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2
            id="testimonials-title"
            className="mb-10 text-3xl font-bold tracking-tight md:text-4xl"
          >
            {title}
          </h2>
        ) : null}
        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
          {testimonials.map((testimonial, index) => (
            <figure
              key={`${testimonial.name}-${index}`}
              className="flex flex-col rounded-2xl border bg-background p-6 shadow-sm"
            >
              <Quote className="h-7 w-7 text-primary" aria-hidden="true" />
              <blockquote className="mt-5 flex-1 text-lg leading-8">
                &ldquo;{testimonial.quote}&rdquo;
              </blockquote>
              <figcaption className="mt-6 flex items-center gap-3 border-t pt-5">
                {testimonial.avatar ? (
                  <Image
                    src={testimonial.avatar}
                    alt=""
                    width={44}
                    height={44}
                    className="h-11 w-11 rounded-full object-cover"
                  />
                ) : null}
                <span>
                  <span className="block font-semibold">{testimonial.name}</span>
                  <span className="block text-sm text-muted-foreground">
                    {[testimonial.role, testimonial.company].filter(Boolean).join(' · ')}
                  </span>
                </span>
              </figcaption>
            </figure>
          ))}
        </div>
      </div>
    </section>
  )
}

import type { LucideIcon } from 'lucide-react'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type ContactMethod = {
  label: string
  value: string
  href: string
  icon?: LucideIcon
}

export type ContactSplitSectionProps = {
  eyebrow?: string
  title: string
  description?: string
  methods: ContactMethod[]
  socialLinks?: Array<{ label: string; href: string }>
  form: React.ReactNode
  formTitle?: string
  className?: string
}

export function ContactSplitSection({
  eyebrow = 'Vamos conversar',
  title,
  description,
  methods,
  socialLinks = [],
  form,
  formTitle = 'Conte sobre o seu projeto',
  className,
}: ContactSplitSectionProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="overflow-hidden rounded-[2rem] border bg-card shadow-sm">
          <div className="grid lg:grid-cols-[0.85fr_1.15fr]">
            <div className="min-w-0 bg-foreground p-7 text-background md:p-10 lg:p-12">
              <p className="text-sm font-semibold uppercase tracking-[0.18em] text-background/70">
                {eyebrow}
              </p>
              <h2 className="mt-4 text-balance text-3xl font-bold tracking-tight md:text-4xl lg:text-5xl">
                {title}
              </h2>
              {description ? (
                <p className="mt-5 max-w-md leading-7 text-background/70">{description}</p>
              ) : null}

              <address className="mt-10 space-y-3 not-italic">
                {methods.map((method) => {
                  const Icon = method.icon
                  return (
                    <a
                      key={`${method.label}-${method.value}`}
                      href={method.href}
                      className="group flex items-center gap-4 rounded-2xl border border-background/15 p-4 transition hover:bg-background/10"
                    >
                      <span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-background/10">
                        {Icon ? (
                          <Icon className="size-5" aria-hidden="true" />
                        ) : (
                          <ArrowUpRight className="size-5" />
                        )}
                      </span>
                      <span className="min-w-0">
                        <span className="block text-xs uppercase tracking-wider text-background/55">
                          {method.label}
                        </span>
                        <span className="mt-1 block font-medium [overflow-wrap:anywhere]">
                          {method.value}
                        </span>
                      </span>
                    </a>
                  )
                })}
              </address>

              {socialLinks.length ? (
                <div className="mt-8 flex flex-wrap gap-2">
                  {socialLinks.map((link) => (
                    <a
                      key={link.label}
                      href={link.href}
                      className="rounded-full border border-background/20 px-3 py-1.5 text-sm transition hover:bg-background hover:text-foreground"
                    >
                      {link.label}
                    </a>
                  ))}
                </div>
              ) : null}
            </div>

            <div className="min-w-0 p-7 md:p-10 lg:p-12">
              <h3 className="mb-7 text-2xl font-semibold">{formTitle}</h3>
              {form}
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'
import Image from 'next/image'
import { PlayCircle } from 'lucide-react'

import { HoverButton } from '@/components/library/primitives/HoverButton'
import { cn } from '@/lib/utils'

export type BannerEditorialProps = {
  eyebrow?: string
  title: ReactNode
  description?: string
  images: readonly { src: string; alt: string }[]
  primaryAction?: { label: string; href: string }
  secondaryAction?: { label: string; href: string; icon?: ReactNode }
  mediaVariant?: 'device' | 'stack' | 'poster'
  tone?: 'light' | 'dark' | 'warm'
  className?: string
}

const tones = {
  light: 'bg-white text-slate-950',
  dark: 'bg-black text-white',
  warm: 'bg-[#f2eee7] text-slate-950',
}

export function BannerEditorial({
  eyebrow,
  title,
  description,
  images,
  primaryAction,
  secondaryAction,
  mediaVariant = 'device',
  tone = 'light',
  className,
}: BannerEditorialProps) {
  const firstImage = images[0]
  const secondImage = images[1]

  return (
    <section
      className={cn('relative overflow-hidden', tones[tone], className)}
      aria-labelledby="banner-editorial-title"
    >
      <div className="container grid min-h-[720px] items-center gap-12 py-20 lg:grid-cols-[1.05fr_.95fr] lg:py-28">
        <div className="relative z-10 max-w-3xl">
          {eyebrow ? (
            <p className="mb-6 text-xs font-bold uppercase tracking-[0.24em] text-primary">
              {eyebrow}
            </p>
          ) : null}
          <h1
            id="banner-editorial-title"
            className="text-5xl font-black uppercase leading-[0.95] tracking-[-0.04em] sm:text-6xl lg:text-8xl"
          >
            {title}
          </h1>
          {description ? (
            <p
              className={cn(
                'mt-8 max-w-xl text-base leading-8',
                tone === 'dark' ? 'text-white/65' : 'text-slate-600',
              )}
            >
              {description}
            </p>
          ) : null}

          {primaryAction || secondaryAction ? (
            <div className="mt-9 flex flex-wrap gap-3">
              {primaryAction ? (
                <HoverButton
                  href={primaryAction.href}
                  effect="expand-icon"
                  size="lg"
                  className="rounded-none px-7"
                >
                  {primaryAction.label}
                </HoverButton>
              ) : null}
              {secondaryAction ? (
                <HoverButton
                  href={secondaryAction.href}
                  effect="lift"
                  variant="outline"
                  size="lg"
                  icon={secondaryAction.icon ?? <PlayCircle className="h-4 w-4" aria-hidden />}
                  iconPosition="left"
                  className={cn(
                    'rounded-none px-7',
                    tone === 'dark' &&
                      'border-white/30 bg-transparent text-white hover:bg-white/10',
                  )}
                >
                  {secondaryAction.label}
                </HoverButton>
              ) : null}
            </div>
          ) : null}
        </div>

        <div className="relative mx-auto h-[560px] w-full max-w-lg">
          {firstImage ? (
            <figure
              className={cn(
                'absolute overflow-hidden bg-muted shadow-2xl',
                mediaVariant === 'device' &&
                  'inset-y-0 right-6 w-[68%] rounded-[3rem] border-[10px] border-slate-900',
                mediaVariant === 'stack' &&
                  'left-0 top-10 h-[78%] w-[72%] rotate-[-5deg] rounded-3xl',
                mediaVariant === 'poster' && 'inset-0 rounded-none',
              )}
            >
              <Image
                src={firstImage.src}
                alt={firstImage.alt}
                fill
